// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(uint256 amount, address eoa) public {
        vm.assume(amount > 0 && amount <= address(this).balance + 1e30);
        vm.assume(eoa != address(this) && eoa != address(c) && eoa.code.length == 0);

        // fund c so its self-destruct refund is observable
        vm.deal(address(c), amount);
        uint256 beforeOrigin = eoa.balance;

        // owner (deployer = address(this)) is msg.sender; force tx.origin to a distinct EOA
        vm.prank(address(this), eoa);
        c.sudicideAnyone();

        // Rule: the refund always lands on the direct caller (owner), never on tx.origin;
        // c is emptied either way, but the origin EOA must have received nothing.
        assertTrue(address(c).balance == 0 && eoa.balance == beforeOrigin);
    }
}
